#!/bin/bash
# Source this file; notify <key> <title> <message> or notify_recover <key> <title> <message>.
_notify_init(){ NOTIFY_STATE_DIR=${NOTIFY_STATE_DIR:-$HOME/.local/state/ochestration/alerts}; NOTIFY_LOG=${NOTIFY_LOG:-$HOME/logs/host/alerts.log}; mkdir -p "$NOTIFY_STATE_DIR" "$(dirname "$NOTIFY_LOG")"; if [ -f "$NOTIFY_LOG" ] && [ "$(wc -c < "$NOTIFY_LOG")" -gt 1048576 ]; then mv -f "$NOTIFY_LOG" "$NOTIFY_LOG.1"; fi; if [ -f "$HOME/.config/ochestration/alert.env" ]; then . "$HOME/.config/ochestration/alert.env"; fi; }
_notify_json_escape(){ local value=$1 nl; nl='
'; value=$(printf '%s' "$value" | sed 's/\\/\\\\/g;s/"/\\"/g'); value=${value//"$nl"/\\n}; printf '%s' "$value"; }
_notify_log(){ printf '[%s] %s\n' "$(date '+%Y-%m-%dT%H:%M:%S%z')" "$*" >> "$NOTIFY_LOG"; }
notify(){ local key=$1 title=$2 message=$3 f now previous suppress=${ALERT_SUPPRESS_SECONDS:-21600} escaped; _notify_init; f="$NOTIFY_STATE_DIR/$key"; now=$(date +%s); previous=$(cat "$f.epoch" 2>/dev/null || echo 0); if [ -f "$f" ] && ((now-previous<suppress)); then _notify_log "SUPPRESSED [$key] $title: $message"; return 0; fi; printf '%s\n' "$now" > "$f.epoch.tmp" && mv -f "$f.epoch.tmp" "$f.epoch"; : > "$f"; _notify_log "ALERT [$key] $title: $message"; if [ -n "${SLACK_WEBHOOK_URL:-}" ]; then escaped=$(_notify_json_escape "$title: $message"); curl -m 10 -fsS -H 'Content-Type: application/json' --data "{\"text\":\"$escaped\"}" "$SLACK_WEBHOOK_URL" >/dev/null 2>&1 || true; fi; return 0; }
notify_recover(){ local key=$1 title=$2 message=$3 escaped; _notify_init; [ -f "$NOTIFY_STATE_DIR/$key" ] || return 0; rm -f "$NOTIFY_STATE_DIR/$key"; _notify_log "RECOVERY [$key] $title: $message"; if [ -n "${SLACK_WEBHOOK_URL:-}" ]; then escaped=$(_notify_json_escape "RECOVERED $title: $message"); curl -m 10 -fsS -H 'Content-Type: application/json' --data "{\"text\":\"$escaped\"}" "$SLACK_WEBHOOK_URL" >/dev/null 2>&1 || true; fi; }
